SELECT 'adidas-hyperboost-run-vs-adidas-adizero-evo-sl',(SELECT id FROM running_shoes WHERE slug='adidas-hyperboost-run'),(SELECT id FROM running_shoes WHERE slug='adidas-adizero-evo-sl'),'category_rival',(SELECT brand || ' ' || model FROM running_shoes WHERE slug='adidas-hyperboost-run') || ' vs ' || (SELECT brand || ' ' || model FROM running_shoes WHERE slug='adidas-adizero-evo-sl'),'Compare source-linked specifications, recorded US prices and intended use.','Different daily-training roles. Do not infer a faster shoe from foam names or historical catalog values; test both for the sessions you run most.',NULL,'Specifications are not a wear test. Check source dates and availability.','["Hyperboost Run has 38/32 mm measured stack and a 6 mm drop; the older Evo SL record has not been reverified on the same basis.","Hyperboost Run is positioned for regular mileage; verify fit and the older model''s current listing before choosing."]',json_object('shoe1',(SELECT replace(category,'_',' ') FROM running_shoes WHERE slug='adidas-hyperboost-run'),'shoe2',(SELECT replace(category,'_',' ') FROM running_shoes WHERE slug='adidas-adizero-evo-sl')) WHERE true ON CONFLICT(slug) DO UPDATE SET comparison_type=excluded.comparison_type,title=excluded.title,meta_description=excluded.meta_description,verdict=excluded.verdict,verdict_winner=NULL,verdict_reason=excluded.verdict_reason,key_differences=excluded.key_differences,best_for=excluded.best_for;
