INSERT INTO running_shoes ("brand","model","slug","series_name","version_number","category","weight","availability","available_from","heel_stack_height","forefoot_stack_height","heel_to_toe_drop","cushioning_level","stability","has_carbon_plate","has_super_foam","price","best_for","release_year","description","source_url","data_source","last_verified","durability_rating","responsiveness_rating","comfort_rating") VALUES ('Skechers','Aero Elite','skechers-aero-elite','Aero Elite',NULL,'racing',6,'available',NULL,40,36,4,'medium','neutral',1,1,224.95,'["racing","speed_work"]',2026,'Road-racing shoe with Hyper Burst Pro supercritical ATPU foam and a carbon-infused TPU Quantum Plate, not an asserted full-carbon plate. Running Warehouse lists 6.0 oz for a men''s US 9 shoe and 40/36 mm stack; the $224.95 price is a snapshot for one colorway.','https://www.runningwarehouse.com/Skechers_Aero_Elite/descpage-SKXAEMA.html','running_warehouse','2026-10-25T00:00:00.000Z',NULL,NULL,NULL) ON CONFLICT(slug) DO NOTHING;
INSERT INTO "_shoe_catalog_import_guard" SELECT CASE WHEN EXISTS(SELECT 1 FROM running_shoes WHERE lower(brand)=lower('Topo Athletic') AND lower(model)=lower('Traverse 2') AND (slug IS NULL OR slug<>'topo-athletic-traverse-2')) THEN 0 ELSE 1 END;
INSERT INTO "_shoe_catalog_import_guard" SELECT CASE WHEN EXISTS(SELECT 1 FROM running_shoes WHERE slug='topo-athletic-traverse-2' AND NOT ("brand" IS 'Topo Athletic' AND "model" IS 'Traverse 2' AND "slug" IS 'topo-athletic-traverse-2' AND "series_name" IS 'Traverse' AND "version_number" IS 2 AND "category" IS 'trail' AND "weight" IS 11.2 AND "availability" IS 'available' AND "available_from" IS NULL AND "heel_stack_height" IS 33 AND "forefoot_stack_height" IS 28 AND "heel_to_toe_drop" IS 5 AND "cushioning_level" IS 'medium' AND "stability" IS 'neutral' AND "has_carbon_plate" IS 0 AND "has_super_foam" IS NULL AND "price" IS 154.95 AND "best_for" IS '["trails"]' AND "release_year" IS 2026 AND "description" IS 'Protective trail and hiking shoe with forefoot rock plate, abrasion-resistant mesh and gaiter attachment. Topo calls it a low-top hiker; Running Warehouse also lists it for technical trails. The men''s US 9 listing is 11.2 oz with 33/28 mm stack. It is not a road trainer.' AND "source_url" IS 'https://www.runningwarehouse.com/Topo_Athletic_Traverse_2/descpage-TO2TRM1.html' AND "data_source" IS 'running_warehouse' AND "last_verified" IS '2026-10-25T00:00:00.000Z' AND "durability_rating" IS NULL AND "responsiveness_rating" IS NULL AND "comfort_rating" IS NULL)) THEN 0 ELSE 1 END;
INSERT INTO running_shoes ("brand","model","slug","series_name","version_number","category","weight","availability","available_from","heel_stack_height","forefoot_stack_height","heel_to_toe_drop","cushioning_level","stability","has_carbon_plate","has_super_foam","price","best_for","release_year","description","source_url","data_source","last_verified","durability_rating","responsiveness_rating","comfort_rating") VALUES ('Topo Athletic','Traverse 2','topo-athletic-traverse-2','Traverse',2,'trail',11.2,'available',NULL,33,28,5,'medium','neutral',0,NULL,154.95,'["trails"]',2026,'Protective trail and hiking shoe with forefoot rock plate, abrasion-resistant mesh and gaiter attachment. Topo calls it a low-top hiker; Running Warehouse also lists it for technical trails. The men''s US 9 listing is 11.2 oz with 33/28 mm stack. It is not a road trainer.','https://www.runningwarehouse.com/Topo_Athletic_Traverse_2/descpage-TO2TRM1.html','running_warehouse','2026-10-25T00:00:00.000Z',NULL,NULL,NULL) ON CONFLICT(slug) DO NOTHING;
